var pad = 34;
var Vmax = 5.2, Pmax = 5.2;
var X = function(v){ return pad + v / Vmax * (W - pad - 14); };
var Y = function(q){ return H - pad - q / Pmax * (H - pad - 16); };

ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(Vmax), Y(0));
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(Pmax));
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.fillText("V", X(Vmax) - 10, Y(0) + 16);
ctx.fillText("P", X(0) - 16, Y(Pmax) + 10);

var V0 = 2.0, P0 = 2.0;
var g = p.gamma;

// isochore: straight up
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(X(V0), Y(P0)); ctx.lineTo(X(V0), Y(4.6)); ctx.stroke();

// isobar: straight right
ctx.beginPath(); ctx.moveTo(X(V0), Y(P0)); ctx.lineTo(X(4.9), Y(P0)); ctx.stroke();

// isotherm through the point
var k = P0 * V0;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
var first = true;
for (var v = 0.85; v <= 5.0; v += 0.05) {
  var q = k / v;
  if (q > Pmax) { first = true; continue; }
  if (first) { ctx.moveTo(X(v), Y(q)); first = false; } else { ctx.lineTo(X(v), Y(q)); }
}
ctx.stroke();

// adiabat through the same point, steeper
var ka = P0 * Math.pow(V0, g);
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.setLineDash([5, 4]);
ctx.beginPath();
first = true;
for (var v2 = 0.85; v2 <= 5.0; v2 += 0.05) {
  var q2 = ka / Math.pow(v2, g);
  if (q2 > Pmax) { first = true; continue; }
  if (first) { ctx.moveTo(X(v2), Y(q2)); first = false; } else { ctx.lineTo(X(v2), Y(q2)); }
}
ctx.stroke();
ctx.setLineDash([]);

// the shared state point
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(V0), Y(P0), 4.5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("isochore  W = 0", X(V0) + 6, Y(4.5));
ctx.fillText("isobar  W = P dV", X(3.1), Y(P0) - 8);
ctx.fillStyle = C.accent;
ctx.fillText("isotherm  PV const", X(2.9), Y(k / 3.6) + 16);
ctx.fillStyle = C.ink;
ctx.fillText("adiabat  PV^g const", X(0.95), Y(ka / Math.pow(1.05, g)) - 6);
ctx.fillStyle = C.faint;
ctx.fillText("start state", X(V0) - 62, Y(P0) + 4);

out.note = "gamma = " + g.toFixed(2) + ". At the shared point the adiabat slope is " + g.toFixed(2) + " times the isotherm slope, so it always falls away faster.";

var pad = 36;
var Vax = 6.4, Pax = 5.6;
var X = function(v){ return pad + v / Vax * (W - pad - 16); };
var Y = function(q){ return H - pad - q / Pax * (H - pad - 30); };

var V1 = 1.0, V2 = p.vmax, P1 = 1.0, P2 = p.phigh;
var cw = p.direction > 0.5;

// axes
ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(Vax), Y(0));
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(Pax));
ctx.stroke();
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.fillText("V (litres)", X(Vax) - 56, Y(0) + 16);
ctx.fillText("P (bar)", X(0) + 4, Y(Pax) + 8);

// enclosed area
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.35;
ctx.beginPath();
ctx.moveTo(X(V1), Y(P1)); ctx.lineTo(X(V2), Y(P1));
ctx.lineTo(X(V2), Y(P2)); ctx.lineTo(X(V1), Y(P2));
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

// the loop
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(X(V1), Y(P2)); ctx.lineTo(X(V2), Y(P2));
ctx.lineTo(X(V2), Y(P1)); ctx.lineTo(X(V1), Y(P1));
ctx.closePath(); ctx.stroke();

// corners, clockwise from top left
var cx = [V1, V2, V2, V1];
var cy = [P2, P2, P1, P1];
var nm = ["A", "B", "C", "D"];
ctx.fillStyle = C.ink;
for (var i = 0; i < 4; i++) {
  ctx.beginPath(); ctx.arc(X(cx[i]), Y(cy[i]), 3.5, 0, Math.PI * 2); ctx.fill();
  ctx.fillText(nm[i], X(cx[i]) + (i === 1 || i === 2 ? 8 : -16), Y(cy[i]) + (i < 2 ? -8 : 16));
}

// moving state point
var per = 4.0;
var u = (t % per) / per * 4;
if (!cw) u = 4 - u;
var seg = Math.floor(u) % 4;
var f = u - Math.floor(u);
var ax = cx[seg], ay = cy[seg];
var bx = cx[(seg + 1) % 4], by = cy[(seg + 1) % 4];
var px = ax + (bx - ax) * f, py = ay + (by - ay) * f;

ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(px), Y(py), 6, 0, Math.PI * 2); ctx.fill();

// work done so far on this leg, in joules: 1 litre * 1 bar = 100 J
var legW = (bx - ax) * f * ay * 100;
var legName = nm[seg] + " to " + nm[(seg + 1) % 4];
var kind = (Math.abs(bx - ax) > 1e-9) ? "isobaric" : "isochoric";

// arrow showing direction of travel
var dx = bx - ax, dy = by - ay;
var L = Math.sqrt(dx * dx * 900 + dy * dy * 900);
if (L > 0) {
  var ux = (X(bx) - X(ax)), uy = (Y(by) - Y(ay));
  var un = Math.sqrt(ux * ux + uy * uy);
  ux /= un; uy /= un;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(X(px), Y(py));
  ctx.lineTo(X(px) + ux * 20, Y(py) + uy * 20);
  ctx.stroke();
}

var Wnet = (P2 - P1) * (V2 - V1) * 100 * (cw ? 1 : -1);
ctx.fillStyle = C.ink;
ctx.fillText("enclosed area = " + Math.abs(Wnet).toFixed(0) + " J", X(0) + 10, Y(Pax) + 26);

out.note = "leg " + legName + " (" + kind + "), work on this leg so far " + legW.toFixed(0) + " J. Net work per cycle " + Wnet.toFixed(0) + " J, so this loop is " + (cw ? "an engine." : "a refrigerator.");

var pad = 36;
var R = 8.31;
var n = 1.0, T = p.temp, Vi = 1.0;
var Vf = p.vf;

var Vax = 6.4;
var Pi = n * R * T / (Vi * 1e-3) / 1e5;
var Pax = Math.max(Pi * 1.25, 1);

var X = function(v){ return pad + v / Vax * (W - pad - 16); };
var Y = function(q){ return H - pad - q / Pax * (H - pad - 26); };

ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(Vax), Y(0));
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(Pax));
ctx.stroke();
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.fillText("V (litres)", X(Vax) - 56, Y(0) + 16);
ctx.fillText("P (bar)", X(0) + 4, Y(Pax) + 8);

var Pof = function(v){ return n * R * T / (v * 1e-3) / 1e5; };

// shaded area under the isotherm from Vi to Vf
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.4;
ctx.beginPath();
ctx.moveTo(X(Vi), Y(0));
for (var v = Vi; v <= Vf + 1e-9; v += (Vf - Vi) / 80) { ctx.lineTo(X(v), Y(Pof(v))); }
ctx.lineTo(X(Vf), Y(0));
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

// the isotherm itself
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
var first = true;
for (var v2 = 0.5; v2 <= Vax; v2 += 0.04) {
  var q = Pof(v2);
  if (q > Pax) { first = true; continue; }
  if (first) { ctx.moveTo(X(v2), Y(q)); first = false; } else { ctx.lineTo(X(v2), Y(q)); }
}
ctx.stroke();

// the isobar at the same start pressure, for comparison
ctx.strokeStyle = C.ink;
ctx.setLineDash([5, 4]);
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(X(Vi), Y(Pi)); ctx.lineTo(X(Vf), Y(Pi)); ctx.stroke();
ctx.setLineDash([]);

// end points
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(Vi), Y(Pi), 4, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(Vf), Y(Pof(Vf)), 4, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("start", X(Vi) - 6, Y(Pi) - 8);
ctx.fillText("end", X(Vf) + 6, Y(Pof(Vf)) - 6);
ctx.fillStyle = C.faint;
ctx.fillText("isobar at the same start pressure", X(Vi) + 8, Y(Pi) + 16);

var Wiso = n * R * T * Math.log(Vf / Vi);
var Wbar = Pi * 1e5 * (Vf - Vi) * 1e-3;

out.note = "isothermal work (shaded) = nRT ln(Vf/Vi) = " + Wiso.toFixed(0) + " J. Along the dashed isobar the same volume change would give P dV = " + Wbar.toFixed(0) + " J.";
